body {
  font-family: 'Inter', sans-serif;
  font-size: 1.125rem; /* 18px base font size */
  line-height: 1.6; /* Optimal for readability */
  color: #333;
}

h2 {
  font-size: 2rem;
  line-height: 1.2; /* Tighter for headings */
  margin-bottom: 0.5em;
}

p {
  margin-bottom: 1em; /* Spacing between paragraphs */
}
